// diagonal plane K-F-B-C → BufferGeometry quad, #cfe4e2 opacity .45, double sided
// labels               → addLabel: A B C D F G H K, −q, +q, E⃗, per-face Φ, Φ_net
// ──────────────────────────────────────────────────────────────────────────

const CRIMSON   = 0xc0392b;
const EDGE_COL  = 0x4a4a4a;
const FACE_BASE = 0xdff0ee;
const POS_COL   = 0xe05a3c;
