  const s = new THREE.InstancedMesh(sg, mat, n);
  const h = new THREE.InstancedMesh(hg, mat, n);
  const m = new THREE.Matrix4();
  positions.forEach((p, i) => {
    m.makeTranslation(p[0], p[1], p[2]);
    s.setMatrixAt(i, m); h.setMatrixAt(i, m);
  });
  s.instanceMatrix.needsUpdate = true; h.instanceMatrix.needsUpdate = true;
  const g = new THREE.Group(); g.add(s, h);
