  },
  {
    title: 'Face-by-face contributions',
    narration: 'Click ABCD, FGHK or a side face to see its outward normal and E·n̂A. The bottom is negative (field entering), the top positive (field leaving), and each vertical side is exactly zero.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: false }
  },
  {
    title: 'The slanted interior plane',
    narration: 'The plane from edge KF down to edge BC is tilted to E, so its flux carries the cosine of the tilt: orientation, not area alone, sets the flux.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: true }
  },
  {
    title: 'Net flux is zero',
    narration: 'Combining all six faces, the +EA from the top cancels the −EA from the bottom and the sides add nothing: no charge is enclosed, so the net flux vanishes.',
    state: { fluxView: 'Net flux', showDiagonal: true }
  }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');

function showStepText(i) {
  stepTitle.textContent = `Step ${i + 1}/${STEPS.length} · ${STEPS[i].title}`;
  stepNarr.textContent = STEPS[i].narration;
}
function goToStep(i) {
