  { fontSize: '14px', color: '#111', bold: true, background: 'rgba(255,255,255,0.9)' });
netLabel.div.style.visibility = 'hidden';

/* ── state + visuals ────────────────────────────────────────────────────── */
let netMode = false;
let selected = null;

function colFor(sign) { return sign > 0 ? POS_COL : sign < 0 ? NEG_COL : ZERO_COL; }

function updateVisuals() {
  FACES.forEach(f => {
    const show = netMode || f === selected;
    let col = FACE_BASE, op = 0.25;
    if (netMode) { col = colFor(f.sign); op = 0.30; }
    if (f === selected) { col = colFor(f.sign); op = 0.50; }
    f.mesh.material.color.setHex(col);
    f.mesh.material.opacity = op;
    f.arrow.visible = show;
    f.arrow.userData.mat.color.setHex(colFor(f.sign));
    f.fluxLabel.div.style.visibility = show ? 'visible' : 'hidden';
    if (f.row) f.row.classList.toggle('active', f === selected);
  });
  netLabel.div.style.visibility = netMode ? 'visible' : 'hidden';
  document.getElementById('netWrap').style.display = netMode ? '' : 'none';
  document.getElementById('faceRows').style.opacity = netMode ? 0.55 : 1;
  document.getElementById('btnFlux').textContent =
    'Flux view: ' + (netMode ? 'Net flux' : 'Face-by-face sum');
}

function selectFace(f) {
  selected = (selected === f) ? null : f;
  updateVisuals();
  if (selected) showPopup(selected.label + ' — signed flux', selected.body);
}

/* ── UI: face rows ──────────────────────────────────────────────────────── */
const rowsDiv = document.getElementById('faceRows');
FACES.forEach(f => {
  const b = document.createElement('button');
  const val = f.flux > 0 ? '+4' : f.flux < 0 ? '\u22124' : '0';
  b.innerHTML = `<span style="display:inline-block;width:11px;height:11px;border-radius:2px;background:#${colFor(f.sign).toString(16).padStart(6, '0')};margin-right:5px;vertical-align:-1px"></span>${f.label} &nbsp;&Phi; = ${val}`;
  b.style.textAlign = 'left';
  b.addEventListener('click', () => { selectFace(f); });
  rowsDiv.appendChild(b);
  f.row = b;
});

/* ── UI: flux view toggle with bar annihilation ─────────────────────────── */
const barPos = document.getElementById('barPos');
const barNeg = document.getElementById('barNeg');
const netText = document.getElementById('netText');
let barTimer = null;

function setFluxView(mode) {
  netMode = (mode === 'Net flux');
  if (netMode) {
    selected = null;
    barPos.style.width = '64px'; barNeg.style.width = '64px';
    barPos.style.opacity = 1; barNeg.style.opacity = 1;
    netText.innerHTML = '+EA &minus; EA + 0 + 0 + 0 + 0';
    clearTimeout(barTimer);
    barTimer = setTimeout(() => {
      barPos.style.width = '0px'; barNeg.style.width = '0px';
      barPos.style.opacity = 0.2; barNeg.style.opacity = 0.2;
      netText.innerHTML = '&Phi;<sub>net</sub> = 0 = q<sub>enc</sub>/&epsilon;<sub>0</sub>';
    }, 420);
  }
  updateVisuals();
}
document.getElementById('btnFlux').addEventListener('click', () => {
  setFluxView(netMode ? 'Face-by-face sum' : 'Net flux');
});

/* ── UI: diagonal plane toggle ──────────────────────────────────────────── */
const chkDiag = document.getElementById('chkDiag');
function setDiagonal(on) { chkDiag.checked = on; diagPlane.visible = on; }
chkDiag.addEventListener('change', () => setDiagonal(chkDiag.checked));

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Uniform field between the plates',
    narration: 'Red arrows run from the positive plate below to the negative plate above: a uniform upward field E fills the region. The cube is an imaginary closed surface placed in it.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: false }
  },
  {
    title: 'Face-by-face contributions',
    narration: 'Click ABCD, FGHK or a side face to see its outward normal and E·n̂A. The bottom is negative (field entering), the top positive (field leaving), and each vertical side is exactly zero.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: false }
  },
  {
    title: 'The slanted interior plane',
    narration: 'The plane from edge KF down to edge BC is tilted to E, so its flux carries the cosine of the tilt: orientation, not area alone, sets the flux.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: true }
  },
  {
    title: 'Net flux is zero',
    narration: 'Combining all six faces, the +EA from the top cancels the −EA from the bottom and the sides add nothing: no charge is enclosed, so the net flux vanishes.',
    state: { fluxView: 'Net flux', showDiagonal: true }
  }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');

function showStepText(i) {
  stepTitle.textContent = `Step ${i + 1}/${STEPS.length} · ${STEPS[i].title}`;
  stepNarr.textContent = STEPS[i].narration;
}
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setFluxView(s.state.fluxView);
  setDiagonal(s.state.showDiagonal);
  if (stepIdx !== 1) { selected = null; updateVisuals(); }
  showStepText(stepIdx);
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── init (controls keep their declared defaults) ──────────────────────── */
setDiagonal(true);
setFluxView('Face-by-face sum');
showStepText(0);

document.getElementById('btnReset').style.display = '';
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
