</div>
<div style="color:#777;margin-top:4px">Drag to orbit · click a cube face or the slanted plane</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC ──────────────────────────────────────────────────────────
// upper plate (y=+3.0)   → PlaneGeometry(9,5) rot -90°X, grey gradient CanvasTexture + LineLoop border
// lower plate (y=-3.0)   → identical, labeled +q
// plate arrows           → InstancedMesh(cyl shaft + cone head) 10×6 per plate, crimson #c0392b
// field-column arrows    → InstancedMesh, 3 vertical columns running plate→plate straight through the cube
// cube edges             → 12 × CylinderGeometry(r=0.022) tubes #4a4a4a + SphereGeometry(0.036) vertex beads
// 6 cube faces           → PlaneGeometry(2,2) Mesh each, translucent cyan-white #dff0ee, clickable
// face normal arrows     → Group(cyl+cone), hidden until the face is selected
// diagonal plane K-F-B-C → 2-triangle BufferGeometry #bfdedb opacity .55 + dark outline tubes
// labels                 → addLabel: A B C D F G H K (serif italic, white pill), −q, +q, E⃗, Φ per face, Φ_net
// ──────────────────────────────────────────────────────────────────────────

const CRIMSON   = 0xc0392b;
const EDGE_COL  = 0x4a4a4a;
const FACE_BASE = 0xdff0ee;
const POS_COL   = 0xe05a3c;
const NEG_COL   = 0x3b6fb5;
const ZERO_COL  = 0x9a9a9a;

const PW = 9.0, PD = 5.0, PY = 3.0;          // plate width (X), depth (Z), |height|

/* ── arrow helpers ──────────────────────────────────────────────────────── */
function arrowGeoms(len, rShaft, rHead) {
  const shaftLen = len * 0.60, headLen = len * 0.40;
  const s = new THREE.CylinderGeometry(rShaft, rShaft, shaftLen, 8);
  s.translate(0, shaftLen / 2, 0);
  const h = new THREE.ConeGeometry(rHead, headLen, 12);
  h.translate(0, shaftLen + headLen / 2, 0);
  return [s, h];
}
function instancedArrows(positions, color, len) {
  const [sg, hg] = arrowGeoms(len, len * 0.075, len * 0.20);
  const mat = new THREE.MeshBasicMaterial({ color });
  const n = positions.length;
  const s = new THREE.InstancedMesh(sg, mat, n);
  const h = new THREE.InstancedMesh(hg, mat, n);
  const m = new THREE.Matrix4();
  positions.forEach((p, i) => {
    m.makeTranslation(p[0], p[1], p[2]);
    s.setMatrixAt(i, m); h.setMatrixAt(i, m);
  });
  s.instanceMatrix.needsUpdate = true; h.instanceMatrix.needsUpdate = true;
  const g = new THREE.Group(); g.add(s, h);
  return g;
}
function singleArrow(len, color) {
  const [sg, hg] = arrowGeoms(len, len * 0.06, len * 0.17);
  const mat = new THREE.MeshBasicMaterial({ color });
  const g = new THREE.Group();
  g.add(new THREE.Mesh(sg, mat), new THREE.Mesh(hg, mat));
  g.userData.mat = mat;
  return g;
}

/* ── plates ─────────────────────────────────────────────────────────────── */
function plateTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 128, 128);
  g.addColorStop(0.0, '#d4d4d4');
  g.addColorStop(0.45, '#f1f1f1');
  g.addColorStop(1.0, '#d0d0d0');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}
const plateTex = plateTexture();
function makePlate(y) {
  const g = new THREE.Group();
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(PW, PD),
    new THREE.MeshBasicMaterial({ map: plateTex, side: THREE.DoubleSide, transparent: true, opacity: 0.97 })
  );
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = y;
  g.add(mesh);
  const hw = PW / 2, hd = PD / 2;
  const pts = [
    new THREE.Vector3(-hw, y, -hd), new THREE.Vector3(hw, y, -hd),
    new THREE.Vector3(hw, y, hd), new THREE.Vector3(-hw, y, hd)
  ];
  g.add(new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x909090 })
  ));
  return g;
}
scene.add(makePlate(PY));
scene.add(makePlate(-PY));

/* ── plate arrow grids (10 × 6 per plate) ──────────────────────────────── */
const plateArrowPos = [];
for (const py of [PY, -PY]) {
  for (let i = 0; i < 10; i++) {
    for (let k = 0; k < 6; k++) {
      plateArrowPos.push([-4.05 + i * 0.9, py + 0.02, -2.0 + k * 0.8]);
    }
  }
}
scene.add(instancedArrows(plateArrowPos, CRIMSON, 0.44));

/* ── field columns: plate → through the cube → plate (no stray arrows) ─── */
const fieldArrowPos = [];
const columns = [[-0.5, 0.5], [0.5, 0.5], [0.0, -0.55]];
const levels = [-2.55, -1.65, -0.75, 0.15, 1.05, 1.95];
for (const [x, z] of columns) for (const y of levels) fieldArrowPos.push([x, y, z]);
scene.add(instancedArrows(fieldArrowPos, CRIMSON, 0.52));

/* ── cube edges + vertex beads ──────────────────────────────────────────── */
const edgeMat = new THREE.MeshBasicMaterial({ color: EDGE_COL });
function tube(a, b, r, mat) {
  const A = new THREE.Vector3(...a), B = new THREE.Vector3(...b);
  const dir = new THREE.Vector3().subVectors(B, A);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8), mat);
  m.position.copy(A).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
const VERTS = {
  A: [-1, -1, 1], B: [1, -1, 1], C: [1, -1, -1], D: [-1, -1, -1],
  F: [-1, 1, 1], G: [1, 1, 1], H: [1, 1, -1], K: [-1, 1, -1]
};
const EDGE_PAIRS = [
  ['A', 'B'], ['B', 'C'], ['C', 'D'], ['D', 'A'],
  ['F', 'G'], ['G', 'H'], ['H', 'K'], ['K', 'F'],
  ['A', 'F'], ['B', 'G'], ['C', 'H'], ['D', 'K']
];
const cubeGroup = new THREE.Group();
EDGE_PAIRS.forEach(([p, q]) => cubeGroup.add(tube(VERTS[p], VERTS[q], 0.022, edgeMat)));
Object.values(VERTS).forEach(v => {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.036, 12, 10), edgeMat);
  s.position.set(...v);
  cubeGroup.add(s);
});
scene.add(cubeGroup);

/* ── six clickable faces ────────────────────────────────────────────────── */
const FACES = [
  { key: 'FGHK', label: 'Top FGHK', center: [0, 1, 0], normal: [0, 1, 0], flux: +4, sign: 1,
    body: 'Top face FGHK. Outward normal n̂ = +ŷ is parallel to E, so Φ = E·n̂ A = +EA = +4 (field lines leave the cube here).' },
  { key: 'ABCD', label: 'Bottom ABCD', center: [0, -1, 0], normal: [0, -1, 0], flux: -4, sign: -1,
    body: 'Bottom face ABCD. Outward normal n̂ = −ŷ is antiparallel to E, so Φ = E·n̂ A = −EA = −4 (field lines enter the cube here).' },
  { key: 'ABGF', label: 'Front ABGF', center: [0, 0, 1], normal: [0, 0, 1], flux: 0, sign: 0,
    body: 'Side face ABGF. Its outward normal n̂ = +ẑ is perpendicular to E, so E·n̂ = 0 and Φ = 0: the field merely grazes this face.' },
  { key: 'BCHG', label: 'Right BCHG', center: [1, 0, 0], normal: [1, 0, 0], flux: 0, sign: 0,
    body: 'Side face BCHG. n̂ = +x̂ ⟂ E, so Φ = E A cos 90° = 0.' },
  { key: 'CDKH', label: 'Back CDKH', center: [0, 0, -1], normal: [0, 0, -1], flux: 0, sign: 0,
    body: 'Side face CDKH. n̂ = −ẑ ⟂ E, so Φ = 0.' },
  { key: 'DAFK', label: 'Left DAFK', center: [-1, 0, 0], normal: [-1, 0, 0], flux: 0, sign: 0,
    body: 'Side face DAFK. n̂ = −x̂ ⟂ E, so Φ = 0.' }
];
const ZAXIS = new THREE.Vector3(0, 0, 1);
const YAXIS = new THREE.Vector3(0, 1, 0);

FACES.forEach(f => {
  const c = new THREE.Vector3(...f.center);
  const n = new THREE.Vector3(...f.normal);
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(2, 2),
    new THREE.MeshBasicMaterial({
      color: FACE_BASE, transparent: true, opacity: 0.30,
      side: THREE.DoubleSide, depthWrite: false
    })
  );
  mesh.position.copy(c);
  mesh.quaternion.setFromUnitVectors(ZAXIS, n);
  mesh.renderOrder = 2;
  scene.add(mesh);
  f.mesh = mesh;

  const arr = singleArrow(0.95, ZERO_COL);
  arr.position.copy(c);
  arr.quaternion.setFromUnitVectors(YAXIS, n);
  arr.visible = false;
  arr.renderOrder = 5;
  scene.add(arr);
  f.arrow = arr;

  registerInteractive(mesh, {
    title: f.label + ' — flux',
    body: f.body,
    tooltip: f.label + ': click for Φ = E·n̂A',
    onClick: () => selectFace(f)
  });
});

/* ── interior diagonal plane K–F–B–C (stronger shading + outline) ──────── */
const diagGroup = new THREE.Group();
const diagGeo = new THREE.BufferGeometry();
diagGeo.setAttribute('position', new THREE.Float32BufferAttribute(
  [...VERTS.K, ...VERTS.F, ...VERTS.B, ...VERTS.K, ...VERTS.B, ...VERTS.C], 3));
diagGeo.computeVertexNormals();
const diagPlane = new THREE.Mesh(diagGeo, new THREE.MeshBasicMaterial({
  color: 0xbfdedb, transparent: true, opacity: 0.60,
  side: THREE.DoubleSide, depthWrite: false
}));
diagPlane.renderOrder = 3;
diagGroup.add(diagPlane);
const diagLineMat = new THREE.MeshBasicMaterial({ color: 0x5f8b87 });
[['K', 'F'], ['F', 'B'], ['B', 'C'], ['C', 'K']].forEach(([p, q]) => {
  const t = tube(VERTS[p], VERTS[q], 0.016, diagLineMat);
  t.renderOrder = 4;
  diagGroup.add(t);
});
scene.add(diagGroup);
registerInteractive(diagPlane, {
  title: 'Slanted interior plane KF–BC',
  body: 'This plane is tilted 45° to E. Its area is larger (A = 2·2√2 = 4√2) but only the cosine of the tilt counts: Φ = E A cosθ = E(4√2)(1/√2) = 4E — exactly the flux of its horizontal projection. Orientation, not area alone, sets the flux.',
  tooltip: 'Tilted plane: Φ = E A cosθ'
});

/* ── camera (after all geometry) ───────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },   // standard isometric, matching the source layout
  rollDeg: 0,
  heightFraction: 0.72
});

/* ── labels ─────────────────────────────────────────────────────────────── */
const VERT_OFFSET = {
  A: [-17, 10], B: [14, 13], C: [17, 8], D: [-17, 2],
  F: [-17, -4], G: [16, 2], H: [17, -6], K: [-4, -17]
};
for (const [name, v] of Object.entries(VERTS)) {
  const e = addLabel(name, new THREE.Vector3(...v), {
    fontSize: '16px', color: '#222', offset: VERT_OFFSET[name],
    background: 'rgba(255,255,255,0.86)'
  });
  e.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  e.div.style.fontStyle = 'italic';
  e.div.style.padding = '0px 3px';
}

addLabel('&minus;q', new THREE.Vector3(PW / 2, PY, PD / 2 - 0.6),
  { fontSize: '15px', color: '#222', offset: [22, -2], background: 'rgba(255,255,255,0.85)' });
addLabel('+q', new THREE.Vector3(PW / 2, -PY, PD / 2 - 0.6),
  { fontSize: '15px', color: '#222', offset: [22, -2], background: 'rgba(255,255,255,0.85)' });

const eLbl = addLabel(
  '<span style="position:relative;display:inline-block;padding-top:3px">' +
  '<b><i>E</i></b><span style="position:absolute;left:0;right:0;top:-6px;font-size:11px;line-height:1">&#8594;</span></span>',
  new THREE.Vector3(-PW / 2 - 0.1, PY - 0.35, PD / 2),
  { fontSize: '18px', color: '#111', offset: [-18, 10] });
eLbl.div.style.fontFamily = 'Georgia, "Times New Roman", serif';

FACES.forEach(f => {
  const p = new THREE.Vector3(...f.center).multiplyScalar(1.75);
  const txt = f.flux > 0 ? '&Phi; = +EA = +4'
    : f.flux < 0 ? '&Phi; = &minus;EA = &minus;4'
      : '&Phi; = 0';
  const col = f.flux > 0 ? '#c0452b' : f.flux < 0 ? '#2f5ea3' : '#5e5e5e';
  const e = addLabel(txt, p, {
    fontSize: '12px', color: col, bold: true,
    background: 'rgba(255,255,255,0.9)',
    offset: f.flux > 0 ? [0, -12] : f.flux < 0 ? [0, 14] : [0, 0]
  });
  e.div.style.visibility = 'hidden';
  f.fluxLabel = e;
});

const netLabel = addLabel('&Phi;<sub>net</sub> = +4 &minus; 4 + 0 = 0', new THREE.Vector3(0, 2.45, 1.0),
  { fontSize: '14px', color: '#111', bold: true, background: 'rgba(255,255,255,0.93)' });
netLabel.div.style.visibility = 'hidden';

/* ── state + visuals ────────────────────────────────────────────────────── */
let netMode = false;
let selected = null;
function colFor(sign) { return sign > 0 ? POS_COL : sign < 0 ? NEG_COL : ZERO_COL; }

function updateVisuals() {
  FACES.forEach(f => {
    const show = netMode || f === selected;
    let col = FACE_BASE, op = 0.30;
    if (netMode) { col = colFor(f.sign); op = 0.34; }
    if (f === selected) { col = colFor(f.sign); op = 0.55; }
    f.mesh.material.color.setHex(col);
    f.mesh.material.opacity = op;
    f.arrow.visible = show;
    f.arrow.userData.mat.color.setHex(colFor(f.sign));
    f.fluxLabel.div.style.visibility = show ? 'visible' : 'hidden';
    if (f.row) f.row.classList.toggle('active', f === selected);
  });
  netLabel.div.style.visibility = netMode ? 'visible' : 'hidden';
  document.getElementById('netWrap').style.display = netMode ? '' : 'none';
  document.getElementById('faceRows').style.opacity = netMode ? 0.55 : 1;
  document.getElementById('btnFlux').textContent =
    'Flux view: ' + (netMode ? 'Net flux' : 'Face-by-face sum');
}

function selectFace(f) {
  selected = (selected === f) ? null : f;
  updateVisuals();
  if (selected) showPopup(selected.label + ' — signed flux', selected.body);
}

/* ── UI: face rows ──────────────────────────────────────────────────────── */
const rowsDiv = document.getElementById('faceRows');
FACES.forEach(f => {
  const b = document.createElement('button');
  const val = f.flux > 0 ? '+4' : f.flux < 0 ? '\u22124' : '0';
  b.innerHTML = `<span style="display:inline-block;width:11px;height:11px;border-radius:2px;background:#${colFor(f.sign).toString(16).padStart(6, '0')};margin-right:5px;vertical-align:-1px"></span>${f.label} &nbsp;&Phi; = ${val}`;
  b.style.textAlign = 'left';
  b.addEventListener('click', () => { selectFace(f); });
  rowsDiv.appendChild(b);
  f.row = b;
});

/* ── UI: flux view toggle with bar annihilation ─────────────────────────── */
const barPos = document.getElementById('barPos');
const barNeg = document.getElementById('barNeg');
const netText = document.getElementById('netText');
let barTimer = null;

function setFluxView(mode) {
  netMode = (mode === 'Net flux');
  if (netMode) {
    selected = null;
    barPos.style.width = '64px'; barNeg.style.width = '64px';
    barPos.style.opacity = 1; barNeg.style.opacity = 1;
    netText.innerHTML = '+EA &minus; EA + 0 + 0 + 0 + 0';
    clearTimeout(barTimer);
    barTimer = setTimeout(() => {
      barPos.style.width = '0px'; barNeg.style.width = '0px';
      barPos.style.opacity = 0.2; barNeg.style.opacity = 0.2;
      netText.innerHTML = '&Phi;<sub>net</sub> = 0 = q<sub>enc</sub>/&epsilon;<sub>0</sub>';
    }, 420);
  }
  updateVisuals();
}
document.getElementById('btnFlux').addEventListener('click', () => {
  setFluxView(netMode ? 'Face-by-face sum' : 'Net flux');
});

/* ── UI: diagonal plane toggle ──────────────────────────────────────────── */
const chkDiag = document.getElementById('chkDiag');
function setDiagonal(on) { chkDiag.checked = on; diagGroup.visible = on; }
chkDiag.addEventListener('change', () => setDiagonal(chkDiag.checked));

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Uniform field between the plates',
    narration: 'Red arrows run from the positive plate below to the negative plate above: a uniform upward field E fills the region. The cube is an imaginary closed surface placed in it.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: false } },
  { title: 'Face-by-face contributions',
    narration: 'Click ABCD, FGHK or a side face to see its outward normal and E·n̂A. The bottom is negative (field entering), the top positive (field leaving), and each vertical side is exactly zero.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: false } },
  { title: 'The slanted interior plane',
    narration: 'The plane from edge KF down to edge BC is tilted to E, so its flux carries the cosine of the tilt: orientation, not area alone, sets the flux.',
    state: { fluxView: 'Face-by-face sum', showDiagonal: true } },
  { title: 'Net flux is zero',
    narration: 'Combining all six faces, the +EA from the top cancels the −EA from the bottom and the sides add nothing: no charge is enclosed, so the net flux vanishes.',
    state: { fluxView: 'Net flux', showDiagonal: true } }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');
function showStepText(i) {
  stepTitle.textContent = `Step ${i + 1}/${STEPS.length} · ${STEPS[i].title}`;
  stepNarr.textContent = STEPS[i].narration;
}
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setFluxView(s.state.fluxView);
  setDiagonal(s.state.showDiagonal);
  if (stepIdx !== 1) { selected = null; updateVisuals(); }
  showStepText(stepIdx);
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── init ───────────────────────────────────────────────────────────────── */
setDiagonal(true);
setFluxView('Face-by-face sum');
showStepText(0);

document.getElementById('btnReset').style.display = '';
